using System.ComponentModel.DataAnnotations;
using Visma.Core.Enums;

namespace Visma.Core.Entities;

/// <summary>
/// One trip to the premises: WHO came (<see cref="Visitor"/>), WHO they saw
/// (<see cref="Host"/>), WHY (<see cref="Purpose"/>) and WHEN (check-in / check-out).
/// A visit is "open" (visitor on-site) while <see cref="CheckOutTime"/> is null.
/// </summary>
public class Visit
{
    /// <summary>Primary key (auto-generated by the database).</summary>
    public int Id { get; set; }

    /// <summary>Foreign key to the visitor.</summary>
    [Required]
    public int VisitorId { get; set; }

    /// <summary>Navigation to the visitor.</summary>
    public Visitor? Visitor { get; set; }

    /// <summary>Foreign key to the host being visited.</summary>
    [Required(ErrorMessage = "Select the person being visited.")]
    [Display(Name = "Person being visited")]
    public int HostId { get; set; }

    /// <summary>Navigation to the host.</summary>
    public Host? Host { get; set; }

    /// <summary>Reason for the visit (category).</summary>
    [Required(ErrorMessage = "Select the purpose of the visit.")]
    [Display(Name = "Purpose of visit")]
    public VisitPurpose Purpose { get; set; }

    /// <summary>Optional free-text details about the purpose, e.g. "Final-year project review".</summary>
    [StringLength(250)]
    public string? Notes { get; set; }

    /// <summary>When the visitor checked in (UTC).</summary>
    [Display(Name = "Checked in")]
    public DateTime CheckInTime { get; set; }

    /// <summary>When the visitor checked out (UTC); null while still on-site.</summary>
    [Display(Name = "Checked out")]
    public DateTime? CheckOutTime { get; set; }

    /// <summary>Derived status: not stored in the database (see VismaDbContext).</summary>
    public VisitStatus Status => CheckOutTime is null ? VisitStatus.CheckedIn : VisitStatus.CheckedOut;

    /// <summary>
    /// How long the visit lasted, or has lasted so far if still open.
    /// </summary>
    /// <param name="nowUtc">Current UTC time (passed in so the result is testable).</param>
    public TimeSpan Duration(DateTime nowUtc) => (CheckOutTime ?? nowUtc) - CheckInTime;
}
